import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

__global__ void conv_transpose2d_fp16_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    half* __restrict__ output,
    int batch,
    int in_c,
    int out_c,
    int H_in,
    int W_in,
    int K,
    int H_out,
    int W_out)
{
    // combine batch and out channel into one dimension
    int bz = blockIdx.z;
    int n  = bz / out_c;          // batch index
    int oc = bz % out_c;          // output channel

    int y  = blockIdx.y * blockDim.y + threadIdx.y; // output height
    int x  = blockIdx.x * blockDim.x + threadIdx.x; // output width

    if (n >= batch || oc >= out_c || y >= H_out || x >= W_out) return;

    float sum = 0.0f;

    // loop over input channels and kernel elements
    for (int ic = 0; ic < in_c; ++ic) {
        for (int ky = 0; ky < K; ++ky) {
            int in_y = y - ky;                 // location in input that contributes
            if (in_y < 0 || in_y >= H_in) continue;
            for (int kx = 0; kx < K; ++kx) {
                int in_x = x - kx;
                if (in_x < 0 || in_x >= W_in) continue;

                // input layout: (N, C_in, H_in, W_in)
                int inp_idx = ((n * in_c + ic) * H_in + in_y) * W_in + in_x;
                // weight layout: (C_in, C_out, K, K)
                int wgt_idx = ((ic * out_c + oc) * K + ky) * K + kx;

                half in_val = input[inp_idx];
                half w_val  = weight[wgt_idx];

                sum += __half2float(in_val) * __half2float(w_val);
            }
        }
    }

    int out_idx = ((n * out_c + oc) * H_out + y) * W_out + x;
    output[out_idx] = __float2half(sum);
}

torch::Tensor conv_transpose2d_fp16(
    torch::Tensor input,
    torch::Tensor weight)
{
    // Expected shapes:
    // input:  (N, C_in, H_in, W_in)
    // weight: (C_in, C_out, K, K)
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be half");
    TORCH_CHECK(weight.dtype() == torch::kHalf, "weight must be half");

    const int64_t batch   = input.size(0);
    const int64_t in_c    = input.size(1);
    const int64_t H_in    = input.size(2);
    const int64_t W_in    = input.size(3);
    const int64_t out_c   = weight.size(1);
    const int64_t K       = weight.size(2);
    TORCH_CHECK(weight.size(2) == weight.size(3), "kernel must be square");
    TORCH_CHECK(K == weight.size(3), "kernel must be square");

    const int64_t H_out = H_in + K - 1; // stride=1, padding=0, output_padding=0
    const int64_t W_out = W_in + K - 1;

    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(input.device())
                       .layout(torch::kStrided);
    torch::Tensor output = torch::empty({batch, out_c, H_out, W_out}, options);

    const dim3 block(16, 16);
    const dim3 grid(
        (W_out + block.x - 1) / block.x,
        (H_out + block.y - 1) / block.y,
        static_cast<unsigned int>(batch * out_c));

    const cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    conv_transpose2d_fp16_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<const half*>(weight.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        static_cast<int>(batch),
        static_cast<int>(in_c),
        static_cast<int>(out_c),
        static_cast<int>(H_in),
        static_cast<int>(W_in),
        static_cast<int>(K),
        static_cast<int>(H_out),
        static_cast<int>(W_out));

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel failed");

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose2d_fp16", &conv_transpose2d_fp16, "FP16 ConvTranspose2d (CUDA)");
}
'''

# compile the inline extension
ext = load_inline(name='conv_transpose2d_fp16_ext',
                  cpp_sources='',
                  cuda_sources=src,
                  functions=['conv_transpose2d_fp16'],
                  verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Supports only stride=1, padding=0, output_padding=0, groups=1, bias=False.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

        # weight shape for ConvTranspose2d: (in_channels, out_channels, k, k)
        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels, kernel_size, kernel_size, dtype=torch.half)
        )
        # simple initialization (mirrors nn.ConvTranspose2d default)
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed convolution using the custom CUDA kernel.
        """
        if x.dtype != torch.half:
            x = x.half()
        return ext.conv_transpose2d_fp16(x, self.weight)

# Example usage (identical to reference test)
if __name__ == "__main__":
    batch_size = 8
    in_channels = 64
    out_channels = 64
    kernel_size = 3
    height = 1024
    width = 1024

    model = ModelNew(in_channels, out_channels, kernel_size).cuda()
    x = torch.rand(batch_size, in_channels, height, width, dtype=torch.half, device='cuda')
    y = model(x)
    print(y.shape)  # should be (8, 64, 1026, 1026)
